#include "data/data_download_manager.h"
#include <iostream>
namespace Data{QByteArray OriginalWrite(const std::vector<DownloadedId>&);std::vector<DownloadedId> OriginalRead(const QByteArray&);}
using namespace Data;
void Emit(const QByteArray &b){auto v=OriginalRead(b);QJsonArray rows;for(const auto &d:v)rows.push_back(QJsonObject{{"id",QString::number(d.download.objectId)},{"type",int(d.download.type)},{"size",QString::number(d.size)},{"started",QString::number(d.started)},{"peer",QString::number(d.itemId.peer.value)},{"msg",QString::number(d.itemId.msg.bare)},{"hash",QString::number(d.peerAccessHash)}});std::cout<<QJsonDocument(QJsonObject{{"op","codec"},{"bytes",QString(b.toHex())},{"canonical",QString(OriginalWrite(v).toHex())},{"rows",rows}}).toJson(QJsonDocument::Compact).constData()<<'\n';}
int main(int argc,char**){if(argc>1){std::string s;while(std::getline(std::cin,s))Emit(QByteArray::fromHex(QByteArray::fromStdString(s)));return 0;}
 for(auto n:{0LL,999LL,-999LL,1000LL,-1000LL,2147483648000LL,9223372036854775807LL,(-9223372036854775807LL-1)})std::cout<<QJsonDocument(QJsonObject{{"op","date"},{"value",QString::number(n)},{"date",DateFromDownloadDate(n)}}).toJson(QJsonDocument::Compact).constData()<<'\n';
 QByteArray good;for(auto size:{0LL,1LL,4194304000LL,4194304001LL,4294967295LL,4294967297LL,-1LL})for(int type:{0,1,7})for(auto path:{QString(),QString(""),QString::fromUtf8("/tmp/файл🙂.bin")}){std::vector<DownloadedId> v;v.push_back({.download={0xffffffffffffffffULL,DownloadType(type)},.started=-1234567890123LL,.path=path,.size=size,.itemId={PeerId(0x0200000000000042ULL),MsgId(-123)},.peerAccessHash=0x8123456789abcdefULL});auto b=OriginalWrite(v);if(size==1&&type==0&&!path.isEmpty())good=b;Emit(b);}
 for(int n=0;n<good.size();++n)Emit(good.first(n));Emit(good+"trailing");Emit(QByteArray());Emit(QByteArray::fromHex("ffffffff"));Emit(QByteArray::fromHex("000186a0"));
 std::vector<DownloadedId> v;v.push_back({.download={7,DownloadType::Photo},.started=1700000000001LL,.path=QString("a"),.size=17,.itemId={PeerId(77),MsgId(3)},.peerAccessHash=9});v.push_back({.download={8,DownloadType::Document},.started=1700000000002LL,.path=QString("b"),.size=18,.itemId={PeerId(78),MsgId(4)},.peerAccessHash=10});Emit(OriginalWrite(v));v.back().path=QString();Emit(OriginalWrite(v));v.pop_back();v.back().path=QString(QChar(0xd800));Emit(OriginalWrite(v));
}
